hooks.paths:
mkdir -p $TMPDIR/probe/src && cat > $TMPDIR/probe/Cargo.toml <<'EOF'
[package]
name = "probe"
version = "0.1.0"
edition = "2021"

[dependencies]
unicode-width = "=0.2.1"
EOF
cat > $TMPDIR/probe/src/main.rs <<'EOF'
use unicode_width::UnicodeWidthChar;
use std::io::Write;

fn main() {
    let mut out = std::io::BufWriter::new(std::fs::File::create("wide.txt").unwrap());
    for cp in 0u32..=0x10FFFF {
        if let Some(ch) = char::from_u32(cp) {
            if let Some(w) = ch.width() {
                if w >= 2 {
                    writeln!(out, "{:X} {}", cp, w).unwrap();
                }
            }
        }
    }
}
EOF
cd $TMPDIR/probe && cargo build --release 2>&1 | tail -20

cat > $TMPDIR/dump.mjs <<'EOF'
import {isFullWidth, isWide} from process.argv[2] + '/lookup.js';
EOF
node -e "console.log('test')"
for v in 1.2.0 1.3.0 1.4.0 1.5.0 1.6.0 1.7.0; do
  cat > $TMPDIR/dump_$v.mjs <<EOF
import {isFullWidth, isWide} from '$TMPDIR/geaw-$v/package/lookup.js';
let lines = [];
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (isFullWidth(cp) || isWide(cp)) lines.push(cp.toString(16).toUpperCase());
}
process.stdout.write(lines.join('\n') + '\n');
EOF
done
echo done

mkdir -p $TMPDIR/gccheck/src && cat > $TMPDIR/gccheck/Cargo.toml <<'EOF'
[package]
name = "gccheck"
version = "0.1.0"
edition = "2021"

[dependencies]
unicode-general-category = "=1.1.0"
EOF
cat > $TMPDIR/gccheck/src/main.rs <<'EOF'
use unicode_general_category::{get_general_category, GeneralCategory};

fn main() {
    for cp in [0x16FE4u32, 0x16FF0, 0x16FF1, 0x3164, 0x17A4, 0x17D8] {
        let ch = char::from_u32(cp).unwrap();
        println!("{:X} {:?}", cp, get_general_category(ch));
    }
}
EOF
cd $TMPDIR/gccheck && cargo run --release 2>&1 | tail -20
